© 2026 Eat &amp; Go S.A. — Menú Digital Criollo Express. Todos los derechos reservados.<span><script>
jQuery(function($) {
  function syncEatGoHeaderCart() {
    var count = 0;
    var totalText = "$0.00";

    var cookieMatch = document.cookie.match(/woocommerce_items_in_cart=(\d+)/);
    if (cookieMatch) {
      count = parseInt(cookieMatch[1], 10);
    } else {
      var badgeText = $(".elementor-button-icon-qty, .cart-count-val, .woocommerce-cart-count-tag").first().text();
      count = parseInt(badgeText, 10) || 0;
    }

    var miniTotal = $(".elementor-menu-cart__subtotal .amount, .woocommerce-mini-cart__total .amount, .elementor-button-text .amount").last().text().trim();
    if (miniTotal) {
      totalText = miniTotal;
    }

    $(".eatgo-header-cart-count").text(count);
    $(".eatgo-header-cart-total").text(totalText);
  }

  syncEatGoHeaderCart();

  $(document).on("added_to_cart removed_from_cart wc_fragments_refreshed wc_fragments_loaded elementor/popup/show", function() {
    setTimeout(syncEatGoHeaderCart, 80);
  });

  $(document).on("click", ".btn-trigger-side-cart, .btn-pill-cart, [data-interaction-id='5a6b498b']", function(e) {
    e.preventDefault();
    if ($(".woofc-cart-toggle").length) {
      $(".woofc-cart-toggle").trigger("click");
    } else if (typeof xoo_wsc_cart !== "undefined") {
      xoo_wsc_cart.open();
    } else if (window.elementorProFrontend && elementorProFrontend.modules && elementorProFrontend.modules.popup) {
      elementorProFrontend.modules.popup.showPopup({ id: 326 });
    } else {
      $(".elementor-menu-cart__toggle_button, .elementor-menu-cart__toggle, .cart-contents").first().trigger("click");
    }
  });
});
</script></span>
